const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const year = 2004;
    const startDate = `${year}-01-01`;
    const endDate = `${year}-12-31`;
    const deathValley = ee.Geometry.Point([-116.865, 36.461]); // Furnace Creek area
    const world = ee.Geometry.BBox(-180, -90, 180, 90); // Global extent

    // 2. Data Acquisition
    const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
        .filterDate(startDate, endDate)
        .select('LST_Day_1km', 'QC_Day');

    // Check if collection is empty
    const collectionSize = modisLST.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No MODIS LST images found for ${year}.`);
        console.log("A: No");
        return;
    }
    console.log(`Total images in ${year}: ${collectionSize}`);

    // 3. Processing
    // Function to mask non-ideal pixels using the QC_Day band.
    // We only want pixels with mandatory QA flags set to 'LST produced, good data quality'.
    const maskQuality = function(image) {
        const qc = image.select('QC_Day');
        // Bits 0-1: Mandatory QA flags
        // 00: LST produced, good data quality
        const qualityMask = qc.bitwiseAnd(0b11).eq(0);
        return image.select('LST_Day_1km').updateMask(qualityMask);
    };

    const maskedLST = modisLST.map(maskQuality);

    // Convert LST from Kelvin to Celsius. The scale factor is 0.02.
    // LST_Celsius = (LST_Kelvin * 0.02) - 273.15
    const toCelsius = function(image) {
        const celsius = image.multiply(0.02).subtract(273.15);
        return celsius.rename('LST_Celsius');
    };

    const lstCelsius = maskedLST.map(toCelsius);

    // 4. Calculation
    // Find the maximum LST for the entire year by creating a max composite.
    const maxLSTImage = lstCelsius.max();

    // Get the maximum temperature in Death Valley
    const deathValleyStats = maxLSTImage.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: deathValley,
        scale: 1000,
        maxPixels: 1e9
    });

    // Get the maximum temperature for the entire world
    const worldStats = maxLSTImage.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: world,
        scale: 1000,
        bestEffort: true,
        maxPixels: 1e12
    });

    const dvMaxTemp = deathValleyStats.get('LST_Celsius').getInfo();
    const worldMaxTemp = worldStats.get('LST_Celsius').getInfo();

    // 5. Validation & Final Answer
    if (dvMaxTemp === null || worldMaxTemp === null) {
        console.log("Could not calculate temperature for one or both regions.");
        console.log("This may be due to a lack of valid pixels after cloud masking.");
        console.log("C2");
        return;
    }

    console.log(`Death Valley Max LST (${year}): ${dvMaxTemp.toFixed(2)} C`);
    console.log(`Global Max LST (${year}): ${worldMaxTemp.toFixed(2)} C`);

    // A small tolerance to account for floating point inaccuracies and the exact
    // pixel location of the global maximum vs. the Death Valley point.
    const tolerance = 0.01;
    if (Math.abs(dvMaxTemp - worldMaxTemp) <= tolerance) {
        console.log("Death Valley recorded the highest maximum LST.");
        console.log("A");
    } else {
        console.log("Death Valley did not record the highest maximum LST.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during initialization or analysis:', e);
        console.log("D");
    }
}

initEE();
